export const MIGRATIONS: Migration[] = [
  { name: "001_init.sql", sql: "-- 001 · Initial schema\n--\n-- requires: timescaledb\n--\n-- Skipped automatically where the TimescaleDB extension is unavailable (Neon,\n-- and most managed Postgres). That is fine and intended: these are the\n-- market-data tables, written by the recorder on a box we control. The\n-- serverless dashboard never writes them, so it does not need them.\n--\n-- Three hypertables mirroring the recorder's three streams, plus NAV history.\n--\n-- Design notes:\n--\n--   * Every table carries `recorded_at` as the time dimension, which is the\n--     moment WE observed the data — not the venue's own timestamp. Those differ\n--     by our latency, and a backtest must replay what we actually saw when we\n--     saw it. Venue timestamps are kept alongside where available.\n--\n--   * Natural keys are used for idempotency so re-importing a JSONL file is\n--     safe. Imports are `ON CONFLICT DO NOTHING`; a re-run after a crash must\n--     not duplicate rows or fail.\n--\n--   * `numeric` rather than `double precision` for anything monetary. Binary\n--     floating point cannot represent 0.1 exactly, and accumulated rounding in\n--     a fee ledger is the kind of error that surfaces as an unexplained\n--     reconciliation mismatch six months later.\n\nCREATE EXTENSION IF NOT EXISTS timescaledb;\n\n-- ---------------------------------------------------------------- quotes\n\nCREATE TABLE IF NOT EXISTS quotes (\n  recorded_at      timestamptz  NOT NULL,\n  venue            text         NOT NULL,\n  asset            text         NOT NULL,\n  kind             text         NOT NULL,   -- spot | perp | error\n  last             numeric,\n  bid              numeric,\n  ask              numeric,\n  spread_bps       numeric,\n  top_of_book_usd  numeric,\n  high_24h         numeric,\n  low_24h          numeric,\n  change_24h_pct   numeric,\n  volume_24h_usd   numeric,\n  funding_rate     numeric,\n  funding_interval_hours numeric,\n  funding_apr      numeric,\n  next_funding_ms  bigint,\n  mark_price       numeric,\n  index_price      numeric,\n  open_interest_usd numeric,\n  venue_ts         bigint,                  -- the venue's own timestamp\n  error            text,                    -- set when kind = 'error'\n  PRIMARY KEY (recorded_at, venue, asset, kind)\n);\n\nSELECT create_hypertable('quotes', 'recorded_at', if_not_exists => TRUE);\n\nCREATE INDEX IF NOT EXISTS quotes_asset_time ON quotes (asset, recorded_at DESC);\nCREATE INDEX IF NOT EXISTS quotes_venue_time ON quotes (venue, recorded_at DESC);\n\n-- --------------------------------------------------------------- funding\n--\n-- Settled funding prints. Keyed on the venue's own settlement time rather than\n-- our observation time — the same print is re-observed on every poll, and we\n-- want one row per settlement, not one per poll.\n\nCREATE TABLE IF NOT EXISTS funding (\n  funding_time  timestamptz NOT NULL,\n  venue         text        NOT NULL,\n  asset         text        NOT NULL,\n  rate          numeric     NOT NULL,\n  apr           numeric     NOT NULL,\n  recorded_at   timestamptz NOT NULL,\n  PRIMARY KEY (funding_time, venue, asset)\n);\n\nSELECT create_hypertable('funding', 'funding_time', if_not_exists => TRUE);\n\nCREATE INDEX IF NOT EXISTS funding_asset_time ON funding (asset, funding_time DESC);\n\n-- ------------------------------------------------------------------ scan\n--\n-- Every opportunity scored and the decision taken. This is the evidence base:\n-- market data records what happened, this records what we would have done.\n\nCREATE TABLE IF NOT EXISTS scan (\n  recorded_at       timestamptz NOT NULL,\n  opportunity_id    text        NOT NULL,\n  strategy          text        NOT NULL,\n  strategy_name     text,\n  asset             text        NOT NULL,\n  route             text,\n  risk_tier         text,\n  sleeve_id         text,\n  sleeve_name       text,\n  gross_bps         numeric,\n  fees_bps          numeric,\n  spread_bps        numeric,\n  slippage_bps      numeric,\n  drag_bps          numeric,\n  net_bps           numeric,\n  net_apr           numeric,\n  breakeven_days    numeric,\n  capital_required_usd numeric,\n  notional_usd      numeric,\n  expected_profit_usd  numeric,\n  funding_apr       numeric,\n  taken             boolean     NOT NULL DEFAULT false,\n  would_take        boolean     NOT NULL DEFAULT false,\n  rejection_code    text,\n  rejection_detail  text,\n  PRIMARY KEY (recorded_at, opportunity_id)\n);\n\nSELECT create_hypertable('scan', 'recorded_at', if_not_exists => TRUE);\n\nCREATE INDEX IF NOT EXISTS scan_strategy_time ON scan (strategy, recorded_at DESC);\nCREATE INDEX IF NOT EXISTS scan_rejection ON scan (rejection_code, recorded_at DESC);\nCREATE INDEX IF NOT EXISTS scan_would_take ON scan (would_take, recorded_at DESC);\n\n-- ----------------------------------------------------------- nav_history\n--\n-- The series the capital ladder reads. Tier promotion requires NAV to hold\n-- above a threshold for 7 consecutive days, which is impossible to evaluate\n-- without this — it is why the ladder is currently frozen at T0.\n\nCREATE TABLE IF NOT EXISTS nav_history (\n  observed_at   timestamptz NOT NULL,\n  nav_usd       numeric     NOT NULL,\n  source        text        NOT NULL,   -- 'manual' | 'venue-sync'\n  PRIMARY KEY (observed_at)\n);\n\nSELECT create_hypertable('nav_history', 'observed_at', if_not_exists => TRUE);\n\n-- -------------------------------------------------------------- retention\n--\n-- Compression rather than deletion. DESIGN.md §4 archives raw data after 30\n-- days; compressed hypertable chunks keep it queryable at roughly 10x smaller,\n-- which is a better trade than throwing away the only copy of what we saw.\n\nALTER TABLE quotes SET (\n  timescaledb.compress,\n  timescaledb.compress_segmentby = 'venue, asset, kind'\n);\n\nSELECT add_compression_policy('quotes', INTERVAL '30 days', if_not_exists => TRUE);\n\nALTER TABLE scan SET (\n  timescaledb.compress,\n  timescaledb.compress_segmentby = 'strategy, asset'\n);\n\nSELECT add_compression_policy('scan', INTERVAL '30 days', if_not_exists => TRUE);\n" },
  { name: "002_app_state.sql", sql: "-- 002 · Durable application state\n--\n-- Everything that previously lived in local JSON files. Needed because a\n-- serverless host has a read-only, ephemeral filesystem — so on Vercel these\n-- tables are the only place config, halt state, the vault and the paper book\n-- can survive a request.\n--\n-- Two shapes, deliberately:\n--\n--   app_state — one row per key, last write wins. Suits mutable singletons:\n--               config, halt state, the credential vault.\n--   app_log   — append-only, ordered. Suits history: audit trails, fills,\n--               orders. Never updated, never deleted except by an explicit\n--               reset, so a crash costs at most the last entry.\n--\n-- Deliberately NOT hypertables. These are small and queried by key rather than\n-- by time range; a hypertable would add chunk management for no benefit. The\n-- market-data tables in 001 are the ones that need Timescale.\n--\n-- This migration must also run on plain Postgres — Neon does not have the\n-- TimescaleDB extension — so nothing here depends on it.\n\nCREATE TABLE IF NOT EXISTS app_state (\n  key        text        PRIMARY KEY,\n  value      jsonb       NOT NULL,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS app_log (\n  id         bigserial   PRIMARY KEY,\n  stream     text        NOT NULL,\n  entry      jsonb       NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Reads are always \"this stream, in order\", so the index matches that exactly.\nCREATE INDEX IF NOT EXISTS app_log_stream_id ON app_log (stream, id);\n" },
  { name: "010_events_core.sql", sql: "-- Event Markets desk. Namespaced into its own schema so the two desks\n-- can never collide on a generic table name like markets or events.\nCREATE SCHEMA IF NOT EXISTS events;\nSET search_path TO events, public;\n\n-- 001: canonical registry + events + odds time-series (Phase 1, spec §8)\n\nCREATE TABLE IF NOT EXISTS venues (\n    id              text PRIMARY KEY,\n    name            text NOT NULL,\n    kind            text NOT NULL,               -- bookie | prediction_market\n    currency        text NOT NULL DEFAULT 'ZAR',\n    softness        double precision DEFAULT 0.5,\n    min_interval_s  double precision DEFAULT 20,\n    homepage        text,\n    enabled         boolean DEFAULT false,\n    created_at      timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS leagues (\n    id       text PRIMARY KEY,                    -- normalized canonical name\n    sport    text NOT NULL,\n    name     text NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS league_aliases (\n    venue_id text NOT NULL DEFAULT '',            -- '' = global alias\n    alias    text NOT NULL,\n    league_id text NOT NULL REFERENCES leagues(id) ON DELETE CASCADE,\n    PRIMARY KEY (alias, venue_id)\n);\n\nCREATE TABLE IF NOT EXISTS teams (\n    id     text PRIMARY KEY,\n    sport  text,\n    name   text NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS team_aliases (\n    venue_id text NOT NULL DEFAULT '',            -- '' = global alias\n    alias    text NOT NULL,\n    team_id  text NOT NULL REFERENCES teams(id) ON DELETE CASCADE,\n    learned  boolean DEFAULT false,               -- self-learned vs seeded\n    PRIMARY KEY (alias, venue_id)\n);\n\nCREATE TABLE IF NOT EXISTS players (\n    id     text PRIMARY KEY,\n    sport  text,\n    name   text NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS player_aliases (\n    venue_id  text NOT NULL DEFAULT '',           -- '' = global alias\n    alias     text NOT NULL,\n    player_id text NOT NULL REFERENCES players(id) ON DELETE CASCADE,\n    PRIMARY KEY (alias, venue_id)\n);\n\nCREATE TABLE IF NOT EXISTS events (\n    id          text PRIMARY KEY,                 -- deterministic content hash\n    sport       text NOT NULL,\n    league_id   text,\n    home        text,\n    away        text,\n    start_time  timestamptz,\n    status      text DEFAULT 'active',\n    created_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_events_start ON events (start_time);\n\nCREATE TABLE IF NOT EXISTS venue_event_links (\n    venue_id   text NOT NULL,\n    event_id   text NOT NULL REFERENCES events(id) ON DELETE CASCADE,\n    venue_ref  text NOT NULL,\n    confidence double precision,\n    matched_by text,                               -- alias | fuzzy | manual\n    created_at timestamptz NOT NULL DEFAULT now(),\n    PRIMARY KEY (venue_id, venue_ref)\n);\n\nCREATE TABLE IF NOT EXISTS markets (\n    id          text PRIMARY KEY,                  -- event_id|market_key\n    event_id    text NOT NULL REFERENCES events(id) ON DELETE CASCADE,\n    market_key  text NOT NULL,\n    market_type text NOT NULL,\n    line        double precision,\n    rules_notes text\n);\n\nCREATE TABLE IF NOT EXISTS match_reviews (\n    id          text PRIMARY KEY,\n    kind        text NOT NULL,                     -- team | league | event\n    venue_id    text,\n    raw_string  text NOT NULL,\n    proposed    text,\n    confidence  double precision,\n    status      text NOT NULL DEFAULT 'pending',\n    context     jsonb,\n    created_at  timestamptz NOT NULL DEFAULT now(),\n    resolved_at timestamptz\n);\n\n-- Odds time-series: Timescale hypertable when available, plain table otherwise.\nCREATE TABLE IF NOT EXISTS odds_snapshots (\n    ts             timestamptz NOT NULL,\n    ts_source      timestamptz,\n    venue_id       text NOT NULL,\n    event_id       text NOT NULL,\n    market_key     text NOT NULL,\n    outcome        text NOT NULL,\n    decimal_odds   double precision,               -- fee-adjusted for PM rows\n    raw_price      double precision,               -- PM raw ask\n    fee_rate       double precision,\n    line           double precision,\n    status         text,\n    executable_zar double precision,\n    token_id       text\n);\nCREATE INDEX IF NOT EXISTS idx_snapshots_evt ON odds_snapshots (event_id, market_key, ts DESC);\nCREATE INDEX IF NOT EXISTS idx_snapshots_venue_ts ON odds_snapshots (venue_id, ts DESC);\n\nDO $$\nBEGIN\n    BEGIN\n        CREATE EXTENSION IF NOT EXISTS timescaledb;\n    EXCEPTION WHEN OTHERS THEN\n        RAISE NOTICE 'timescaledb extension unavailable — odds_snapshots stays a plain table';\n    END;\n    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'timescaledb') THEN\n        PERFORM create_hypertable('odds_snapshots', 'ts', if_not_exists => TRUE,\n                                  migrate_data => TRUE);\n    END IF;\nEND $$;\n" },
  { name: "011_events_opportunities.sql", sql: "-- Event Markets desk. Namespaced into its own schema so the two desks\n-- can never collide on a generic table name like markets or events.\nCREATE SCHEMA IF NOT EXISTS events;\nSET search_path TO events, public;\n\n-- 002: opportunities, lifecycles, alerts, placements (Phase 1, spec §8)\n\nCREATE TABLE IF NOT EXISTS opportunities (\n    id                      text PRIMARY KEY,\n    opp_type                text NOT NULL,\n    event_id                text NOT NULL,\n    event_label             text,\n    sport                   text,\n    league                  text,\n    start_time              timestamptz,\n    market_key              text NOT NULL,\n    margin_pct              double precision NOT NULL,\n    score                   double precision,\n    score_breakdown         jsonb,                -- persisted for later ML (spec §13)\n    urgency                 text,\n    timing                  text,\n    rule_risk               boolean DEFAULT false,\n    mirrored                boolean DEFAULT false,\n    total_stake_zar         double precision,\n    guaranteed_profit_zar   double precision,\n    executable_zar_per_leg  double precision,\n    fx_rate                 double precision,\n    first_seen              timestamptz NOT NULL,\n    last_seen               timestamptz NOT NULL,\n    peak_margin_pct         double precision,\n    state                   text NOT NULL DEFAULT 'active',\n    window_s                double precision,\n    notes                   jsonb\n);\nCREATE INDEX IF NOT EXISTS idx_opps_state_score ON opportunities (state, score DESC);\nCREATE INDEX IF NOT EXISTS idx_opps_first_seen ON opportunities (first_seen);\n\nCREATE TABLE IF NOT EXISTS opportunity_legs (\n    opportunity_id  text NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,\n    idx             int NOT NULL,\n    venue_id        text NOT NULL,\n    outcome         text NOT NULL,\n    selection_label text,\n    odds            double precision NOT NULL,\n    raw_price       double precision,\n    fee_rate        double precision,\n    stake_zar       double precision,\n    deep_link       text,\n    rules_group     text,\n    is_pm           boolean DEFAULT false,\n    token_id        text,\n    max_stake_zar   double precision,\n    order_index     int,\n    PRIMARY KEY (opportunity_id, idx)\n);\n\nCREATE TABLE IF NOT EXISTS opportunity_lifecycles (\n    id              bigserial PRIMARY KEY,\n    opportunity_id  text NOT NULL,\n    ts              timestamptz NOT NULL DEFAULT now(),\n    margin_pct      double precision,\n    state           text NOT NULL,                -- detected | update | expired\n    note            text\n);\nCREATE INDEX IF NOT EXISTS idx_lifecycles_opp ON opportunity_lifecycles (opportunity_id, ts);\n\nCREATE TABLE IF NOT EXISTS alerts (\n    id              bigserial PRIMARY KEY,\n    opportunity_id  text NOT NULL,\n    channel         text NOT NULL DEFAULT 'telegram',\n    kind            text,                         -- new | improved\n    ok              boolean,\n    dry_run         boolean,\n    payload         jsonb,\n    ts              timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS placements (\n    id               bigserial PRIMARY KEY,\n    opportunity_id   text NOT NULL,\n    status           text NOT NULL,               -- placed | missed | voided | partial\n    leg_idx          int,\n    actual_odds      double precision,\n    actual_stake_zar double precision,\n    note             text,\n    ts               timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_placements_opp ON placements (opportunity_id);\n" },
  { name: "012_events_phase2_stubs.sql", sql: "-- Event Markets desk. Namespaced into its own schema so the two desks\n-- can never collide on a generic table name like markets or events.\nCREATE SCHEMA IF NOT EXISTS events;\nSET search_path TO events, public;\n\n-- 003: Phase 2 accounts & promos — created EMPTY now so the schema is interfaced\n-- from day one (spec §1, §8). STRICT POLICY: one genuine person per account set;\n-- no multi-accounting, ever (spec: explicit non-goals).\n\nCREATE TABLE IF NOT EXISTS persons (\n    id          text PRIMARY KEY,\n    full_name   text NOT NULL,\n    -- One genuine person per account set — enforced at application level too.\n    note        text,\n    created_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS accounts (\n    id            text PRIMARY KEY,\n    person_id     text NOT NULL REFERENCES persons(id),\n    venue_id      text NOT NULL,\n    health_state  text NOT NULL DEFAULT 'healthy',  -- healthy | watched | limited | gubbed | closed\n    opened_at     timestamptz,\n    closed_at     timestamptz,\n    UNIQUE (person_id, venue_id)                    -- one account per person per venue\n);\n\nCREATE TABLE IF NOT EXISTS bankrolls (\n    account_id   text PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,\n    balance_zar  double precision NOT NULL DEFAULT 0,\n    updated_at   timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS promos (\n    id                 text PRIMARY KEY,\n    venue_id           text NOT NULL,\n    name               text NOT NULL,\n    promo_type         text NOT NULL,              -- signup | reload | boost\n    bonus_pct          double precision,\n    max_bonus_zar      double precision,\n    min_odds           double precision,\n    rollover_multiple  double precision,\n    one_per_household  boolean DEFAULT true,\n    terms              text,\n    active             boolean DEFAULT true\n);\n\nCREATE TABLE IF NOT EXISTS wagering_progress (\n    id                      bigserial PRIMARY KEY,\n    account_id              text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,\n    promo_id                text NOT NULL REFERENCES promos(id),\n    required_turnover_zar   double precision NOT NULL,\n    completed_turnover_zar  double precision NOT NULL DEFAULT 0,\n    deadline                timestamptz,\n    state                   text DEFAULT 'in_progress'\n);\n\nCREATE TABLE IF NOT EXISTS account_health_events (\n    id          bigserial PRIMARY KEY,\n    account_id  text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,\n    ts          timestamptz NOT NULL DEFAULT now(),\n    event_type  text NOT NULL,                     -- stake_limited | promo_excluded | kyc_request | ...\n    detail      jsonb\n);\n\n-- Promo structures researched in the spec (§23 key findings) — reference rows for\n-- Phase-2 EV/hedge math prototyping. Terms must be re-verified before use.\nINSERT INTO promos (id, venue_id, name, promo_type, bonus_pct, max_bonus_zar, min_odds,\n                    rollover_multiple, one_per_household, terms, active)\nVALUES\n  ('wsb_signup_2026', 'wsb', 'WSB 100% deposit match', 'signup', 100, 20000, 1.50, 5, true,\n   'One bonus per person/household/IP. 5x rollover at min odds 1.50. RE-VERIFY before relying on.', false),\n  ('betway_signup_2026', 'betway_sa', 'Betway signup bonus', 'signup', 100, 1000, NULL, 3, true,\n   '3x rollover. RE-VERIFY before relying on.', false),\n  ('betfred_signup_2026', 'betfred_sa', 'Betfred SA signup bonus', 'signup', 100, 5000, NULL, 5, true,\n   '5x rollover. RE-VERIFY before relying on.', false),\n  ('hwb_bonus_2026', 'hollywoodbets', 'Hollywoodbets bonus (odds >= 1.50)', 'signup', NULL, NULL, 1.50,\n   NULL, true, 'Bonuses require odds >= 5/10 (1.50). RE-VERIFY before relying on.', false)\nON CONFLICT (id) DO NOTHING;\n" },
  { name: "013_events_runtime_flags.sql", sql: "-- Event Markets desk. Namespaced into its own schema so the two desks\n-- can never collide on a generic table name like markets or events.\nCREATE SCHEMA IF NOT EXISTS events;\nSET search_path TO events, public;\n\n-- 004: cross-process runtime flags.\n--\n-- The kill switch has to work from wherever the operator is standing — the hosted\n-- dashboard on Vercel, the local terminal, or a Compose deployment — so it lives in\n-- the shared database rather than in one process's hot state. The Python scheduler\n-- mirrors this into Redis each sweep; the Next.js API reads and writes it directly.\n\nCREATE TABLE IF NOT EXISTS runtime_flags (\n    key        text PRIMARY KEY,\n    value      jsonb NOT NULL,\n    updated_at timestamptz NOT NULL DEFAULT now(),\n    updated_by text\n);\n\nINSERT INTO runtime_flags (key, value, updated_by)\nVALUES ('kill_switch', 'false'::jsonb, 'migration')\nON CONFLICT (key) DO NOTHING;\n" },
];
